queries.sphinxql:
create table t (body text, chunks float_vector_array knn_type='hnsw' hnsw_similarity='cosine' model_name='sentence-transformers/all-MiniLM-L6-v2' from='body' chunk_strategy='fixed' max_tokens='8' overlap_tokens='2');
insert into t (id, body) values (1, 'Hello world. alpha beta gamma delta epsilon zeta eta theta. omega target phrase.');
insert into t (id, body) values (2, 'unrelated text for a second row');


select id, highlight({knn_chunk=1},'body') from t where knn(chunks, 2, 'target phrase') order by id asc;

select id, highlight({knn_chunk=1},'body') from t where match('target phrase') and knn(chunks, 2, 'target phrase') order by id asc;

select id, highlight({knn_chunk=1},'body') from t where knn(chunks, 2, 'target phrase', {rescore=1}) order by id asc;

select id, highlight({knn_chunk=1},'body') from t where knn(chunks, 2, 'target phrase', {fullscan=1, rescore=0}) order by id asc;

select id, highlight({knn_chunk=1},'body','target phrase') from t order by id asc;

select id, highlight({knn_chunk=0},'body','target phrase') from t where knn(chunks, 2, 'target phrase') order by id asc;

select id, highlight({before_match='knn_chunk'},'body','target phrase') from t where knn(chunks, 2, 'target phrase') order by id asc;


select highlight({knn_chunk=1},'wrong') from t where knn(chunks, 1, 'target phrase');
select highlight({knn_chunk=1},body) from t where knn(chunks, 1, 'target phrase');
select highlight({knn_chunk=1}) from t where knn(chunks, 1, 'target phrase');
select highlight({knn_chunk=1, html_strip_mode='none'},'body') from t where knn(chunks, 1, 'target phrase');
select highlight({knn_chunk=1, passage_boundary='sentence'},'body') from t where knn(chunks, 1, 'target phrase');
select snippet(body, 'target phrase', 'knn_chunk=1') from t;


flush ramchunk t;
select id, highlight({knn_chunk=1},'body') from t where knn(chunks, 2, 'target phrase', {rescore=1}) order by id asc;
insert into t (id, body) values (3, 'alpha beta gamma delta epsilon zeta eta theta iota kappa lambda third row target phrase three');
flush ramchunk t;
optimize table t option sync=1, cutoff=1;
select id, highlight({knn_chunk=1},'body') from t where knn(chunks, 3, 'target phrase', {rescore=1}) order by id asc;

insert into t (id, body) values (4, 'alpha beta gamma delta epsilon zeta eta theta iota kappa lambda ram row target phrase four');
select id, highlight({knn_chunk=1},'body') from t where knn(chunks, 4, 'target phrase') order by id asc;

select id, highlight({knn_chunk=1},'body') from t where knn(chunks, 4, 'target phrase') order by id asc;
drop table t;


create table t (body text, chunks float_vector_array knn_type='hnsw' hnsw_similarity='cosine' model_name='sentence-transformers/all-MiniLM-L6-v2' from='body' chunk_strategy='fixed' max_tokens='8') html_strip='1';
insert into t (id, body) values (1, '<p class="intro">alpha beta gamma delta epsilon zeta eta theta</p><p>iota kappa lambda <b>stripped</b> target phrase here</p>');
select id, highlight({knn_chunk=1},'body') from t where knn(chunks, 1, 'target phrase');
select id, highlight({knn_chunk=1},'body') from t where match('target phrase') and knn(chunks, 1, 'target phrase');
flush ramchunk t;
select id, highlight({knn_chunk=1},'body') from t where knn(chunks, 1, 'target phrase');
drop table t;


create table t (body text, v float_vector_array knn_type='hnsw' knn_dims='2' hnsw_similarity='l2');
insert into t values (1, 'manual target phrase text', [[1,0],[0,1]]);
select highlight({knn_chunk=1},'body','target phrase') from t where knn(v, 1, (1,0));
drop table t;
create table t (body text, v float_vector knn_type='hnsw' hnsw_similarity='cosine' model_name='sentence-transformers/all-MiniLM-L6-v2' from='body' chunk_strategy='mean' max_tokens='8');
insert into t (id, body) values (1, 'alpha beta gamma delta epsilon zeta eta theta target phrase omega');
select highlight({knn_chunk=1},'body','target phrase') from t where knn(v, 1, 'target phrase');
drop table t;


create table t (body1 text, body2 text, s string, chunks float_vector_array knn_type='hnsw' hnsw_similarity='cosine' model_name='sentence-transformers/all-MiniLM-L6-v2' from='body1,body2' chunk_strategy='fixed' max_tokens='8');
insert into t (id, body1, body2, s) values (1, 'target phrase', 'other', 'x');
select highlight({knn_chunk=1},'body1') from t where knn(chunks, 1, 'target phrase');
drop table t;
create table t (body text, s string, chunks float_vector_array knn_type='hnsw' hnsw_similarity='cosine' model_name='sentence-transformers/all-MiniLM-L6-v2' from='s' chunk_strategy='fixed' max_tokens='8');
insert into t (id, body, s) values (1, 'stored body', 'target phrase');
select highlight({knn_chunk=1},'body') from t where knn(chunks, 1, 'target phrase');
drop table t;
